    dump_sle("responsiveness", exp.responsiveness);
    json << ",";
    dump_sle("reliability", exp.reliability);
    json << ",";
    dump_sle("rf_health", exp.rf_health);
    json << "},";

    json << "\"service_health\":{";
    dump_sle("dns", exp.dns_service);
    json << ",";
    dump_sle("tcp_connect", exp.tcp_connect);
    json << ",";
    dump_sle("tcp_rtt", exp.tcp_rtt);
    json << ",";
    dump_sle("http_access", exp.http_access);
    json << ",";
    dump_sle("captive_portal", exp.captive_portal);
    json << ",";
    dump_sle("active_dns", exp.active_dns);
    json << ",";
    dump_sle("active_tcp", exp.active_tcp);
    json << ",";
    dump_sle("active_https", exp.active_https);
    json << ",";
    dump_sle("active_portal", exp.active_portal);
    json << "},";

    json << "\"warnings\":[";
    for (size_t i = 0; i < exp.warnings.size(); ++i) {
        json << "\"" << escapeJsonString(exp.warnings[i]) << "\"";
        if (i + 1 < exp.warnings.size()) json << ",";
    }
    json << "],";

    json << "\"primary_issue\":"
         << (exp.primary_issue.has_value()
                 ? ("\"" + escapeJsonString(exp.primary_issue.value()) + "\"")
                 : "null");
    json << ",";

    json << "\"link_type\":\"" << edgeLinkTypeToString(exp, topo) << "\"";

    if (topo && topo->collected) {
        if (topo->mac_address) {
            json << ",\"mac_address\":\"" << escapeJsonString(*topo->mac_address) << "\"";
        }
        if (topo->ip_address) {
            json << ",\"ip_address\":\"" << escapeJsonString(*topo->ip_address) << "\"";
        }
        if (topo->gateway_ip) {
            json << ",\"gateway_ip\":\"" << escapeJsonString(*topo->gateway_ip) << "\"";
        }
        json << ",\"dns_servers\":[";
        for (size_t i = 0; i < topo->dns_servers.size(); ++i) {
            json << "\"" << escapeJsonString(topo->dns_servers[i]) << "\"";
            if (i + 1 < topo->dns_servers.size()) json << ",";
        }
        json << "]";
        if (topo->ap_ssid) {
            json << ",\"ap_ssid\":\"" << escapeJsonString(*topo->ap_ssid) << "\"";
        }
        if (topo->ap_bssid) {
            json << ",\"ap_bssid\":\"" << escapeJsonString(*topo->ap_bssid) << "\"";
        }
    }
    json << "}";
    return json.str();
}

