    18	        ConfigString tenant{""};
    19	        // 设备唯一标识（同时是服务端资产主键），字符集 [A-Za-z0-9._-]
    20	        ConfigString device_id{""};
    21	        // 现场标识（site_id）：多网关部署时**同一现场的多台网关共享此值**，
    22	        // 云端据此把多探针观测聚合成一个现场视图。
    23	        //
    24	        // 留空则回落 device_id —— 即 Phase 1/3a 的 "1 Gateway = 1 Site"
    25	        // 行为完全不变，单网关部署无需配置此项。
    26	        ConfigString site_id{""};
    27	        // 设备预共享令牌，作为 X-Edge-Token 头（非机密中的机密，仍是凭据）
    28	        ConfigString token{""};
    29	        // Ed25519 私钥 PEM 路径；与 token 一起决定上报身份
    30	        ConfigString private_key_path{""};
    31	        // 密钥标识（服务端据 X-Edge-Key-Id 选择信任锚）
    32	        ConfigString key_id{""};
    33	        // 云端下行验签公钥（Ed25519 PEM）：非空时，telemetry 响应里的
    34	        // pending_actions 必须携带对该数组字节的有效 detached 签名，
    35	        // 否则整批拒绝（S1）。留空 = 不验签（兼容旧云端，迁移期默认）。
    36	        ConfigString cloud_public_key_path{""};
    37	        // 允许非回环明文 HTTP 上报（仅实验环境）。默认 false：
    38	        // edge.url 指向非回环地址且 scheme 为 http 时拒绝加载，
    39	        // 防止令牌/签名密钥在链路上裸奔（S1#3）。
    40	        std::atomic<bool> allow_insecure_http{false};
    41	        // 上报周期；与评估节奏（quality 线程）对齐，一个周期最多一条
